mapper.select:
select 
	a.ind_Id indId,
	b.ind_name indName,
	b.remark 
from stt_stress_indicator a 
left JOIN stt_indicator b on a.ind_id=b.ind_id


			and a.model_id=#{modelId, jdbcType=VARCHAR}


		and b.ind_ype=#{indType, jdbcType=VARCHAR}


		and a.STT_BUSI_TYPE=#{sttBusiType, jdbcType=VARCHAR}
